import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";

const Sidebar = () => {
  const roles = useSelector((state) => state.auth.roles || []);
  const username = useSelector((state) => state.auth.username);
  const isAdmin = roles.includes("ROLE_ADMIN");
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("roles");
    localStorage.removeItem("username");
    localStorage.removeItem("name");
    window.location.href = "/login";
  };

  // اگر کاربر لاگین نکرده، سایدبار نمایش داده نشود
  if (!localStorage.getItem("token")) {
    return null;
  }

  return (
    <div
      className="d-flex flex-column p-3 bg-light"
      style={{
        width: "220px",
        height: "100vh",
      }}
    >
      <div className="flex-grow-1">
        <h4 className="mb-4">داشبورد</h4>
        <div className="mb-3 text-center">
          <small className="text-muted">خوش آمدید</small>
          <br />
          <strong>{username || "کاربر"}</strong>
        </div>
        <hr />
        <ul className="nav nav-pills flex-column mb-auto">
          <li className="nav-item mb-2">
            <Link to="/" className="nav-link text-dark">
              کارمندان
            </Link>
          </li>
          <li className="nav-item mb-2">
            <Link to="/products" className="nav-link text-dark">
              محصولات
            </Link>
          </li>
          {/* فقط برای ادمین‌ها نمایش داده شود */}
          {isAdmin && (
            <li className="nav-item mb-2">
              <Link to="/users" className="nav-link text-dark">
                کاربران
              </Link>
            </li>
          )}
        </ul>
      </div>

      <div className="mt-auto">
        <button className="btn btn-outline-danger w-100" onClick={handleLogout}>
          خروج
        </button>
      </div>
    </div>
  );
};

export default Sidebar;
